defmodule MythweaverWeb.CoreComponents.AvatarPlaceholder do
  @moduledoc """
  The picture shown wherever a character has no avatar: a bust in front of a whirlpool, white in
  light mode and black in dark mode (`prefers-color-scheme`, as `assets/css/tokens.css` switches).

  The artwork is drawn once per page, as the `<symbol>` in `avatar_placeholder_sprite/1` (in the
  root layout, beside Iconex's icon sprite), and every `avatar_placeholder/1` is a `<use>` of it, so
  a transcript full of avatar-less messages carries one copy of the paths instead of one per message.

  Every color is a shade of `--avatar-color`, read where the placeholder sits; unset, it is the app's
  `--primary` (`assets/css/tokens.css`), which follows the user's primary hue. The shades are
  `color-mix`es of it with black and white. Styles are global (`MythweaverWeb.ColocatedCSS`): the
  shapes render in `<use>`'s shadow tree, where no scope marker reaches.

  Corners come from `--avatar-radius`, set on the avatar's box (which uses it for its own corners
  too). An HTML wrapper clips the picture with `clip-path`, rather than the box's `overflow` or
  the `<svg>`'s own `border-radius`/`clip-path`: WebKit rounds neither for SVG content inside a
  sticky container (a chat message's aside).
  """

  use Phoenix.Component

  @symbol "mw-avatar-placeholder"

  attr :class, :any, default: nil, doc: "layout hook for the caller; the picture fills its box by default"

  @doc "A character with no avatar: fills its container, cropped to its shape (`slice`)."
  def avatar_placeholder(assigns) do
    assigns = assign(assigns, :href, "#" <> @symbol)

    ~H"""
    <span class={["mw-avatar", @class]} aria-hidden="true">
      <svg viewBox="0 0 128 128" preserveAspectRatio="xMidYMid slice" focusable="false">
        <use href={@href} />
      </svg>
    </span>
    """
  end

  @doc "The artwork every `avatar_placeholder/1` uses; render once per page."
  def avatar_placeholder_sprite(assigns) do
    assigns = assign(assigns, :id, @symbol)

    ~H"""
    <style :type={MythweaverWeb.ColocatedCSS}>
      span.mw-avatar {
        --mw-avatar-c: var(--avatar-color, var(--primary));
        display: block;
        inline-size: 100%;
        block-size: 100%;
        clip-path: inset(0 round var(--avatar-radius, 0));
      }

      span.mw-avatar > svg {
        display: block;
        inline-size: 100%;
        block-size: 100%;
      }

      .mw-avatar-bg {
        fill: color-mix(in oklch, var(--mw-avatar-c) 45%, black);
      }
      .mw-avatar-s1 {
        fill: color-mix(in oklch, var(--mw-avatar-c) 75%, black);
      }
      .mw-avatar-s2 {
        fill: var(--mw-avatar-c);
      }
      .mw-avatar-s3 {
        fill: color-mix(in oklch, var(--mw-avatar-c) 65%, white);
      }
      .mw-avatar-s4 {
        fill: color-mix(in oklch, var(--mw-avatar-c) 35%, white);
      }
      .mw-avatar-glow {
        fill: color-mix(in oklch, var(--mw-avatar-c) 12%, white);
      }

      /* White on light mode, outlined dark so it holds against the bright eye of the whirlpool;
         black on dark mode, outlined light so it holds against the dark corners. */
      .mw-avatar-person {
        fill: white;
        stroke: color-mix(in oklch, var(--mw-avatar-c) 50%, black);
        stroke-width: 0.75;
      }

      @media (prefers-color-scheme: dark) {
        .mw-avatar-person {
          fill: black;
          stroke: color-mix(in oklch, var(--mw-avatar-c) 55%, white);
        }
      }
    </style>
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="0"
      height="0"
      aria-hidden="true"
      style="position: absolute; overflow: hidden"
    >
      <symbol id={@id} viewBox="0 0 128 128">
